    if(tags.includes("area")&&!tags.includes("projectile")||tags.includes("melee")||tags.includes("orbit")){const x=target?.x??this.x,y=target?.y??this.y;game.explosion(x,y,area,damage*.88,this.skinColors()[0],35,src,false);return}
    const football=tags.includes("football")||beh.toLowerCase().includes("football"),homing=tags.includes("homing")||beh.toLowerCase().includes("homing")||beh==="multiTarget";game.projectiles.push(new Projectile({x:this.x,y:this.y,vx:n.x*speed,vy:n.y*speed,radius:Math.max(3,Math.min(8,(d.size||5)*.72)),damage,life:Math.max(.9,Math.min(2.0,range/speed+0.45)),color:this.skinColors()[0],pierce:Math.max(0,Math.min(2,d.pierce||0)),bounce:Math.max(0,Math.min(1,d.bounce||0)),knockback:(d.knockback||18)*.45,weapon:src,behavior:homing?"homing":"straight",homingStrength:homing?3.2:0,projectileStyle:football?"football":null,statSourceId:"clones"}))
