  update(dt){this.life-=dt;if(this.life<=0||this.hp<=0){this.dead=true;return}for(const p of game.enemyProjectiles){if(p.dead)continue;if(this.inside(p.x,p.y,p.radius)){p.dead=true;this.hp-=Math.max(2,p.damage||8);game.spark(p.x,p.y,"#d99455",3)}}for(const e of game.enemies){if(e.dead||e.isCaptive)continue;if(!this.inside(e.x,e.y,e.size))continue;const q=this.local(e.x,e.y),side=q.y>=0?1:-1,nx=-Math.sin(this.angle)*side,ny=Math.cos(this.angle)*side,push=this.height/2+e.size-Math.abs(q.y)+3;e.x+=nx*push;e.y+=ny*push;const ready=this.hitTimes.get(e.id)||0;if(ready<=game.time){this.hitTimes.set(e.id,game.time+.55);this.hp-=Math.max(1,e.damage*.24);game.damageEnemy(e,this.weapon.getStats().damage*.36,{source:this.weapon,canCrit:false,knockback:this.weapon.getStats().knockback*.35,fromX:this.x,fromY:this.y,silent:true})}}if(this.hp<=0){this.dead=true;game.spark(this.x,this.y,"#c97b43",12);game.guardianNetworkTrigger()}}
