class Enemy{
  constructor(type,x,y,scale=1,elite=null){const d=ENEMY_DEFINITIONS[type];this.id=NEXT_ID++;this.type=type;this.def=d;this.x=x;this.y=y;this.size=d.size;this.maxHp=d.hp*scale;this.hp=this.maxHp;this.speed=Math.min(d.speed*(1+(scale-1)*.16),d.speed*GAME_CONFIG.enemySpeedCapMult);this.damage=d.damage*(.85+(scale-.85)*.45);this.xp=Math.max(1,Math.round(d.xp*(.8+scale*.3)));this.knockbackResistance=d.knockbackResistance||0;this.dead=false;this.statuses=new Map();this.flash=0;this.aiTimer=rand(1.3,.4);this.shotTimer=rand(2,.6);this.elite=elite;this.isBoss=false;this.specialId=d.specialId||null;this.shieldTimer=0;this.shieldActive=false;this.regen=0;if(elite)this.applyElite(elite)}
  applyElite(mod){this.maxHp*=2.6;this.hp=this.maxHp;this.damage*=1.5;this.size*=1.25;this.xp*=5;if(mod==="Swift")this.speed*=1.35;if(mod==="Giant"){this.size*=1.35;this.maxHp*=1.5;this.hp=this.maxHp}if(mod==="Regenerating")this.regen=this.maxHp*.012;if(mod==="Shielded")this.shieldActive=true;if(mod==="Frenzied"){this.speed*=1.18;this.damage*=1.25}}
  applyStatus(type,duration,strength,source){const cur=this.statuses.get(type);if(cur){cur.duration=Math.max(cur.duration,duration);cur.strength=Math.max(cur.strength,strength);cur.stacks=Math.min(5,(cur.stacks||1)+1)}else this.statuses.set(type,{type,duration,strength,source,stacks:1,tick:.5});game.events.emit("onStatusApplied",{enemy:this,type})}
  updateStatus(dt){let speedMult=1;for(const [k,s] of this.statuses){s.duration-=dt;s.tick-=dt;if(k==="slow")speedMult*=Math.max(.25,1-s.strength);if(k==="freeze")speedMult=0;if(k==="burn"&&s.tick<=0){s.tick=.5;game.damageEnemy(this,s.strength,{source:s.source,canCrit:false,damageType:"fire",silent:true})}if(k==="poison"&&s.tick<=0){s.tick=.6;game.damageEnemy(this,s.strength*s.stacks,{source:s.source,canCrit:false,damageType:"poison",silent:true})}if(s.duration<=0)this.statuses.delete(k)}return speedMult}
  update(dt){
    this.flash=Math.max(0,this.flash-dt);
    if(this.regen)this.hp=Math.min(this.maxHp,this.hp+this.regen*dt);
    this.shieldTimer-=dt;
    if(this.type==="shielded"&&this.shieldTimer<=0){
      this.shieldTimer=4;
      this.shieldActive=!this.shieldActive;
    }
    let sm=this.updateStatus(dt);if(game.timeDilation>0)sm*=.38;
    if(sm===0)return;
    const p=game.player;
    const dx=p.x-this.x,dy=p.y-this.y,d=Math.hypot(dx,dy)||1;let nx=dx/d,ny=dy/d;if(this.statuses.has("confuse")){nx=-nx;ny=-ny}
    this.aiTimer-=dt;
    this.shotTimer-=dt;

    switch(this.def.behavior){
      case "chase":
        this.x+=nx*this.speed*sm*dt;
        this.y+=ny*this.speed*sm*dt;
        break;
      case "charge":
        if(this.chargeTime>0){
          this.chargeTime-=dt;
          this.x+=this.chargeVX*dt;
          this.y+=this.chargeVY*dt;
        }else if(this.aiTimer<=0){
          this.aiTimer=2.5;
          this.chargeTime=.42;
          this.chargeVX=nx*this.speed*4.2;
          this.chargeVY=ny*this.speed*4.2;
          game.effects.push(new WaveEffect(this.x,this.y,35,.25,0,0,null,"#ffd36b"));
        }else{
          this.x+=nx*this.speed*.65*sm*dt;
          this.y+=ny*this.speed*.65*sm*dt;
        }
        break;
      case "shoot":
        if(d>260){
          this.x+=nx*this.speed*sm*dt;
          this.y+=ny*this.speed*sm*dt;
        }else if(d<180){
          this.x-=nx*this.speed*sm*dt;
          this.y-=ny*this.speed*sm*dt;
        }
        if(this.shotTimer<=0){
          this.shotTimer=1.7;
          game.enemyProjectiles.push(new Projectile({x:this.x,y:this.y,vx:nx*240,vy:ny*240,radius:5,damage:this.damage,life:3,color:"#ff79d8",owner:"enemy",critAllowed:false}));
        }
        break;
      case "shield":
        this.x+=nx*this.speed*sm*dt;
        this.y+=ny*this.speed*sm*dt;
        break;
      case "explode":
        this.x+=nx*this.speed*sm*dt;
        this.y+=ny*this.speed*sm*dt;
        if(d<42){
          game.player.takeDamage(this.damage,{fromX:this.x,fromY:this.y,enemy:this,physical:true});
          game.explosion(this.x,this.y,62,this.damage*.3,"#ff463e",55,null);
          this.die(false);
        }
        break;
      case "teleport":
        this.x+=nx*this.speed*.6*sm*dt;
        this.y+=ny*this.speed*.6*sm*dt;
        if(this.aiTimer<=0){
          this.aiTimer=3.4;
          const a=Math.random()*Math.PI*2,rr=rand(300,180);
          this.x=p.x+Math.cos(a)*rr;
          this.y=p.y+Math.sin(a)*rr;
          game.spark(this.x,this.y,"#9d74ff",12);
        }
        break;
    }

    if(!this.dead&&d<this.size+p.radius){
      p.takeDamage(this.damage,{fromX:this.x,fromY:this.y,enemy:this,physical:true});
      const push=normalize(this.x-p.x,this.y-p.y);
      this.x+=push.x*14;
      this.y+=push.y*14;
    }
  }
  die(drop=true){if(this.dead)return;this.dead=true;game.kills++;game.score+=this.isBoss?5000:this.specialId?1000:this.elite?250:20;game.events.emit("onEnemyKilled",{enemy:this});game.onAnyEnemyKilled(this);if(this.specialId)game.onSpecialEnemyKilled(this);game.spark(this.x,this.y,this.elite?"#e56bff":"#ff5368",this.elite?18:8);if(drop){let xpValue=this.xp;if(this.elite&&game.player.passiveLevel("fortune_bold")>0)xpValue=Math.round(xpValue*(1+.25*game.player.passiveLevel("fortune_bold")));game.gems.push(new XPGem(this.x,this.y,xpValue));const surgeon=game.player.passiveLevel("field_surgeon"),fortune=game.player.passiveLevel("fortune_bold"),chance=GAME_CONFIG.pickupChance*(1+game.player.passiveLevel("scavenger")*.18+surgeon*.08+(this.elite?fortune*.10:0));if(Math.random()<chance)game.pickups.push(new Pickup(this.x+rand(18,-18),this.y+rand(18,-18),pick(["medkit","medkit","health","magnet","bomb","frenzy","shield","xp"])));if((this.elite||this.isBoss)&&game.player.passiveLevel("golden_touch")>0&&Math.random()<.05*game.player.passiveLevel("golden_touch")*(1+game.player.luck*.05))game.pickups.push(new Pickup(this.x+rand(22,-22),this.y+rand(22,-22),"golden_boost"));if(this.elite&&Math.random()<GAME_CONFIG.chestEliteChance*(1+game.player.luck*.05+fortune*.12))game.chests.push(new Chest(this.x,this.y))}if(this.def.split){for(let i=0;i<3;i++){const e=new Enemy("swarmer",this.x+rand(20,-20),this.y+rand(20,-20),Math.max(1,game.difficulty*.9));game.enemies.push(e)}}if(this.elite==="Explosive")game.explosion(this.x,this.y,70,22,"#ff7b40",40,null)}
  render(g){g.save();g.translate(this.x,this.y);if(this.elite){g.shadowBlur=16;g.shadowColor="#e66bff";g.strokeStyle="#e66bff";g.lineWidth=3;g.beginPath();g.arc(0,0,this.size+6,0,Math.PI*2);g.stroke()}if(this.shieldActive){g.strokeStyle="#94aaff";g.lineWidth=4;g.beginPath();g.arc(0,0,this.size+5,0,Math.PI*2);g.stroke()}g.fillStyle=window.VSX_SETTINGS_V5?.flashColor?.(this.def.color,this.flash>0)||(this.flash>0?"#fff":this.def.color);const s=this.size;switch(this.def.shape){case"triangle":g.beginPath();g.moveTo(0,-s);g.lineTo(s,s);g.lineTo(-s,s);g.closePath();g.fill();break;case"diamond":g.rotate(Math.PI/4);g.fillRect(-s*.75,-s*.75,s*1.5,s*1.5);break;case"circle":g.beginPath();g.arc(0,0,s,0,Math.PI*2);g.fill();break;case"hex":g.beginPath();for(let i=0;i<6;i++){const a=i*Math.PI/3;const x=Math.cos(a)*s,y=Math.sin(a)*s;i?g.lineTo(x,y):g.moveTo(x,y)}g.closePath();g.fill();break;default:g.fillRect(-s,-s,s*2,s*2)}if(this.def.label){g.shadowBlur=0;g.fillStyle=this.def.labelColor||"#fff";g.font=`900 ${Math.max(13,s*.95)}px Arial`;g.textAlign="center";g.textBaseline="middle";g.fillText(this.def.label,0,1)}for(const [k] of this.statuses){g.fillStyle=STATUS_DEFINITIONS[k]?.color||"#fff";g.fillRect(-s,s+4,Math.max(4,s*.6),3);break}g.restore()}
}

