function angleDiff(a,b){let d=(a-b+Math.PI)%(Math.PI*2)-Math.PI;return d<-Math.PI?d+Math.PI*2:d}

class GoalkeeperGloveEffect{
  constructor(weapon,stats,angle){this.weapon=weapon;this.stats=stats;this.angle=angle;this.life=this.maxLife=stats.duration;this.dead=false;this.caught=[];this.released=false}
  centers(){const p=game.player,nx=Math.cos(this.angle),ny=Math.sin(this.angle),px=-ny,py=nx,d=this.stats.range*.62,side=this.stats.size*1.35;return[{x:p.x+nx*d+px*side,y:p.y+ny*d+py*side},{x:p.x+nx*d-px*side,y:p.y+ny*d-py*side}]}
  update(dt){this.life-=dt;for(const c of this.centers())for(const p of game.enemyProjectiles){if(p.dead)continue;if(Math.hypot(p.x-c.x,p.y-c.y)<p.radius+this.stats.size){this.caught.push({damage:p.damage||8,color:p.color||"#fff"});p.dead=true;game.spark(c.x,c.y,"#dff4ff",4)}}if(this.life<=0&&!this.released){this.released=true;const count=Math.min(12,this.caught.length);for(let i=0;i<count;i++){const t=game.findNearest(game.player.x,game.player.y,720);if(!t)break;const a=Math.atan2(t.y-game.player.y,t.x-game.player.x)+(i-(count-1)/2)*.07,spd=620;game.projectiles.push(new Projectile({x:game.player.x,y:game.player.y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,radius:this.weapon.special==="goldenReturn"?6:4,damage:this.stats.damage*(this.weapon.special==="goldenReturn"?1.8:1),life:1.6,color:this.weapon.special==="goldenReturn"?"#ffd84d":"#d8f3ff",weapon:this.weapon,pierce:this.weapon.special==="goldenReturn"?1:0,projectileStyle:this.weapon.special==="goldenReturn"?"goldenBall":null}))}if(count)game.audio.beep(880,.08,"triangle",.02);this.dead=true}}
  render(g){for(const c of this.centers()){g.save();g.translate(c.x,c.y);g.rotate(this.angle);g.shadowBlur=12;g.shadowColor="#eaf8ff";g.fillStyle="#f6fbff";g.fillRect(-this.stats.size*.35,-this.stats.size*.85,this.stats.size*.7,this.stats.size*1.7);g.beginPath();g.arc(this.stats.size*.25,0,this.stats.size*.72,-Math.PI*.55,Math.PI*.55);g.fill();g.strokeStyle="#6fb4e8";g.lineWidth=2;g.stroke();g.restore()}}
}

