  chain(w,s){let current=game.findNearest(game.player.x,game.player.y,s.range);if(!current)return;const used=new Set(),pts=[{x:game.player.x,y:game.player.y}];for(let i=0;i<s.chain&&current;i++){used.add(current.id);pts.push({x:current.x,y:current.y});const res=game.damageEnemy(current,s.damage,{source:w,canCrit:true,damageType:"electric",status:w.evolutionId?{type:"shock",duration:2,strength:.15}:null});current=game.findNearest(current.x,current.y,180,null,used)}if(w.special==="finalPulse"||w.special==="network"){const p=pts[pts.length-1];game.explosion(p.x,p.y,w.special==="network"?80:48,s.damage*.45,"#f5ea62",0,w)}game.lightning.push({pts,life:.12,max:.12,color:w.evolutionId?"#fff9a6":"#f4e85f"});game.audio.beep(820,.05,"sawtooth",.015)},
