  beam(w,s){const t=game.findNearest(game.player.x,game.player.y,s.range);if(!t)return;const p={x:game.player.x,y:game.player.y},n=normalize(t.x-p.x,t.y-p.y),end={x:p.x+n.x*s.range,y:p.y+n.y*s.range};game.beams.push({x1:p.x,y1:p.y,x2:end.x,y2:end.y,life:.09,color:w.evolutionId?"#f7c2ff":"#ff5fcf",width:w.evolutionId?6:4});const candidates=game.grid.queryCircle((p.x+end.x)/2,(p.y+end.y)/2,s.range*.55+40);const hits=[];for(const e of candidates){if(e.dead)continue;const d=pointSegDist(e.x,e.y,p.x,p.y,end.x,end.y);if(d<e.size+s.size)hits.push(e)}hits.sort((a,b)=>dist2(p,a)-dist2(p,b));const limit=(w.level>=4||w.special==="prism")?hits.length:1;for(let i=0;i<Math.min(limit,hits.length);i++)game.damageEnemy(hits[i],s.damage,{source:w,canCrit:true,damageType:"arcane"});if((w.level>=5||w.special==="prism")&&hits[0]){const t2=game.findNearest(hits[0].x,hits[0].y,220,hits[0].id);if(t2){game.beams.push({x1:hits[0].x,y1:hits[0].y,x2:t2.x,y2:t2.y,life:.09,color:"#f0a5ff",width:3});game.damageEnemy(t2,s.damage*.65,{source:w,canCrit:true})}}},
