  trySpecialSpawns(){const specials=[{id:"mbappe",min:GAME_CONFIG.mbappeMinTime,pity:GAME_CONFIG.mbappePityTime,chance:GAME_CONFIG.mbappeSpawnChance},{id:"ronaldo",min:GAME_CONFIG.ronaldoMinTime,pity:GAME_CONFIG.ronaldoPityTime,chance:GAME_CONFIG.specialSpawnChance},{id:"messi",min:GAME_CONFIG.messiMinTime,pity:GAME_CONFIG.messiPityTime,chance:GAME_CONFIG.specialSpawnChance}];for(const s of specials){if(game.specialSpawned[s.id]||game.time<s.min)continue;const age=Math.max(0,game.time-s.min),chance=s.chance*(1+Math.min(1.5,age/120));if(game.time>=s.pity||Math.random()<chance)this.spawnSpecial(s.id)}}
